theme.css:
#wemd{color:#2d3a2e;background-color:#fafbf5;font-family:'Source Han Serif SC', 'Noto Serif SC', 'STKaiti', 'KaiTi', serif;font-size:17px;line-height:2;letter-spacing:0.03em;text-align:justify;padding:44px 32px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.5em;text-indent:2em}
#wemd h1{font-size:28px;font-weight:400;color:$colors.accent;margin-top:2.5em;margin-bottom:1.2em;text-align:center}
#wemd h2{font-size:22px;font-weight:600;color:$colors.text_primary;margin-top:2em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid $colors.accent;padding-bottom:.4em}
#wemd h3{font-size:18px;font-weight:600;color:$colors.accent;margin-top:1.6em;margin-bottom:0.6em}
#wemd h4{font-size:16px;font-weight:400;color:$colors.text_secondary;margin-top:1.3em;margin-bottom:0.5em}
#wemd blockquote{border-left:4px solid $colors.quote_border;background:$colors.quote_background;padding:16px 22px;color:$colors.text_secondary;font-style:normal;margin:1.2em 0}
#wemd code{background-color:$colors.code_background;color:$colors.accent;padding:2px 6px;border-radius:3px;font-size:0.9em;font-family:'Fira Code', monospace}
#wemd pre{background:$colors.code_background;border-radius:4px;padding:16px 20px;line-height:1.5;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid $colors.border;padding:10px 14px}
#wemd th{background:$colors.table_header_bg}
#wemd tr:nth-child(even){background:$colors.table_stripe_bg}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:8px}
#wemd li::marker{color:$colors.accent}
#wemd hr{border:0;border-top:1px solid $colors.accent;margin:2.5em 0;width:20%}
#wemd img{max-width:100%;height:auto;border-radius:4px}
#wemd figcaption{font-size:13px;color:$colors.text_secondary;text-align:center}
#wemd a{color:$colors.link_color;text-decoration:none}
#wemd strong{color:#4a7c59;font-weight:700}
#wemd mark{background:$colors.highlight_bg;padding:2px 6px;border-radius:3px}
